for item in items:
    db_item = {
        "PK": {"S": f"RESTAURANT#{RESTAURANT_UUID}"},
        "SK": {"S": f"ITEM#{item['uuid']}"},
        "uuid": {"S": item["uuid"]},
        "name": {"S": item["name"]},
        "imageUrl": {"S": item["imageUrl"]},
        "allergens": {"S": item["allergens"]},
        "nutritionalValues": {"S": item["nutritionalValues"]},
        "price": {"N": str(item["price"])},
        "description": {"S": item["description"]},
        "categories": {"L": [{"S": c} for c in item["categories"]]},
        "category_name": {"S": item["categories"][0]}
    }
    subprocess.run(["aws", "dynamodb", "put-item", "--table-name", "borne-appetit-products", "--item", json.dumps(db_item)], capture_output=True)
    print(f"✓ {item['name']}")

